{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Chronic psychological stress has been proposed as a contributor to metabolic dysfunction; however, evidence linking perceived stress to MetS and its individual components remains inconsistent.",
      "reason": "The abstract background describes the current state of knowledge (stress proposed as contributor to metabolic dysfunction) and notes important uncertainties (evidence linking perceived stress to MetS and components remains inconsistent)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "The Perceived Stress Scale (PSS) is a widely validated instrument for assessing subjective stress, yet its association with metabolic outcomes has not been systematically synthesised.",
      "reason": "The abstract explains the importance and need for the review by stating that although PSS is widely used, its association with metabolic outcomes has not been systematically synthesised, justifying the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence describes existing similar systematic reviews, explains the need relative to them, or cites previous reviews; therefore this conditional item is not reported in the provided evidence."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "Chronic psychological stress has been proposed as a contributor to metabolic dysfunction; however, evidence linking perceived stress to MetS and its individual components remains inconsistent.",
      "reason": "This review concerns associations between perceived stress and metabolic parameters rather than intervention effects; a mechanism of action for an intervention is not applicable to the manuscript's focus."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "The Perceived Stress Scale (PSS) is a widely validated instrument for assessing subjective stress, yet its association with metabolic outcomes has not been systematically synthesised.",
      "reason": "The review does not evaluate complex interventions or delivery contexts, so a logic model is not applicable based on the provided evidence."
    }
  ],
  "confidence": "85"
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "The objective of this study was to systematically review the evidence and evaluate the association between perceived stress, measured using the PSS, and metabolic parameters related to MetS.",
      "reason": "The manuscript explicitly states the study objective as a systematic review evaluating the association between perceived stress (PSS) and metabolic parameters, directly addressing the review question."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_9",
      "quote": "Studies were eligible if they: (1) used an observational or interventional design reporting baseline associations; (2) enrolled adults aged \u226518 years; (3) assessed chronic psychological stress with PSS-10 or PSS-14; (4) reported MetS diagnosis or at least one metabolic component; and (5) provided sufficient data to derive effect estimates.",
      "reason": "The review focuses on associations between perceived stress and metabolic outcomes (including baseline associations from observational or interventional designs) rather than planned intervention comparisons; therefore specifying PICO-style planned comparisons for intervention effects is not applicable."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "Studies were eligible if they: (1) used an observational or interventional design reporting baseline associations; (2) enrolled adults aged \u226518 years; (3) assessed chronic psychological stress with PSS-10 or PSS-14; (4) reported MetS diagnosis or at least one metabolic component; and (5) provided sufficient data to derive effect estimates. Case reports, narrative reviews, editorials, conference abstracts, paediatric studies, and studies using nonPSS instruments were excluded.",
      "reason": "The manuscript explicitly lists study designs, age requirement, specific stress instruments (PSS-10/14), outcome types (MetS or metabolic components), data sufficiency, and excluded publication/study types—covering the study characteristics used to determine eligibility."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_7;text_9",
      "quote": "Only studies published from 2015 onward were considered; this date threshold was determined to focus on evidence generated after widespread adoption of the PSS-10 as the dominant instrument in metabolic research, and is acknowledged as a limitation.\n\nCase reports, narrative reviews, editorials, conference abstracts, paediatric studies, and studies using nonPSS instruments were excluded.",
      "reason": "The review specifies a dissemination year restriction (from 2015) and excludes certain report types (e.g., conference abstracts), but does not state any language restrictions or fully describe all publication/report-status criteria (language not mentioned)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement distinguishing exclusion due to outcomes not being measured versus outcomes not being reported is present in the provided evidence."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_14;text_11",
      "quote": "BMI was the most frequently reported variable (24 studies), followed by systolic and diastolic blood pressure (12 studies each), and waist circumference (10 studies). Other metabolic markers were less commonly reported: glucose in 7 studies, triglycerides and HbA1c in 5 each, HOMA-IR and HDL in 4 each, CRP and total cholesterol in 3 each, and LDL in only 2 studies.\n\nUnivariate meta-regression analyses examined the association between each metabolic risk factor and PSS z-scores using the rma.mv function (REML) in the metafor package (v4.6-0) in R (v4.4.2).",
      "reason": "The review specifies the outcome groups (individual metabolic variables with counts) and describes that syntheses were conducted as univariate meta-regressions linking each metabolic risk factor to PSS z-scores, thereby specifying groups used in each synthesis and linking them to the review's comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Only studies published from 2015 onward were considered; this date threshold was determined to focus on evidence generated after widespread adoption of the PSS-10 as the dominant instrument in metabolic research, and is acknowledged as a limitation.",
      "reason": "A rationale for the notable restriction on study eligibility (publication year cutoff) is provided, explaining it was chosen to focus on evidence after widespread adoption of the PSS-10."
    }
  ],
  "confidence": "85"
}

